import React from "react";

class ModulItem extends React.Component {
    render() {
        return (
                <div class="d-flex align-items-center justify-content-between gap-3 mb-3">
                    <div class="d-flex align-items-center gap-3">
                        <img src="img/aaa.png" alt="" class="rounded-circle border"
                            style={{width: "50px"}}/>
                        <div>
                            <strong>Name</strong>
                            <small>
                                shayad you
                            </small>
                            <br/>
                        </div>
                    </div>
                    <div>
                        <div class="mt-3">
                            <a href="/follow/{{ $followed->user_id }}" class="btn btn-theme active rounded-pill px-4">
                                Unfollow
                            </a>
                        </div>
                    </div>
                </div>
        );
    }
}
export default ModulItem;
